#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum Stmt {
    BlockStmt(BlockStmt),
    ExprStmt(ExprStmt),
    AssignStmt(AssignStmt),
    DeclStmt(DeclStmt),
    IfStmt(IfStmt),
    StaticIfStmt(StaticIfStmt),
    ForStmt(ForStmt),
    StaticForStmt(StaticForStmt),
    WhileStmt(WhileStmt),
    DoWhileStmt(DoWhileStmt),
    SwitchStmt(SwitchStmt),
    ReturnStmt(ReturnStmt),
    BreakStmt(BreakStmt),
    BarrierStmt(BarrierStmt),
    ReorderStmt(ReorderStmt),
    AtomicStmt(AtomicStmt),
    AnnotatedStmt(AnnotatedStmt),
    EmptyStmt(EmptyStmt),
}

impl AstNode for Stmt {
    fn can_cast(kind: SyntaxKind) -> bool {
        matches!(
            kind,
            SyntaxKind::BLOCK_STMT
                | SyntaxKind::EXPR_STMT
                | SyntaxKind::ASSIGN_STMT
                | SyntaxKind::DECL_STMT
                | SyntaxKind::IF_STMT
                | SyntaxKind::STATIC_IF_STMT
                | SyntaxKind::FOR_STMT
                | SyntaxKind::STATIC_FOR_STMT
                | SyntaxKind::WHILE_STMT
                | SyntaxKind::DO_WHILE_STMT
                | SyntaxKind::SWITCH_STMT
                | SyntaxKind::RETURN_STMT
                | SyntaxKind::BREAK_STMT
                | SyntaxKind::BARRIER_STMT
                | SyntaxKind::REORDER_STMT
                | SyntaxKind::ATOMIC_STMT
                | SyntaxKind::ANNOTATED_STMT
                | SyntaxKind::EMPTY_STMT
        )
    }

    fn cast(syntax: SyntaxNode) -> Option<Self> {
        let res = match syntax.kind() {
            SyntaxKind::BLOCK_STMT => Stmt::BlockStmt(BlockStmt { syntax }),
            SyntaxKind::EXPR_STMT => Stmt::ExprStmt(ExprStmt { syntax }),
            SyntaxKind::ASSIGN_STMT => Stmt::AssignStmt(AssignStmt { syntax }),
            SyntaxKind::DECL_STMT => Stmt::DeclStmt(DeclStmt { syntax }),
            SyntaxKind::IF_STMT => Stmt::IfStmt(IfStmt { syntax }),
            SyntaxKind::STATIC_IF_STMT => Stmt::StaticIfStmt(StaticIfStmt { syntax }),
            SyntaxKind::FOR_STMT => Stmt::ForStmt(ForStmt { syntax }),
            SyntaxKind::STATIC_FOR_STMT => Stmt::StaticForStmt(StaticForStmt { syntax }),
            SyntaxKind::WHILE_STMT => Stmt::WhileStmt(WhileStmt { syntax }),
            SyntaxKind::DO_WHILE_STMT => Stmt::DoWhileStmt(DoWhileStmt { syntax }),
            SyntaxKind::SWITCH_STMT => Stmt::SwitchStmt(SwitchStmt { syntax }),
            SyntaxKind::RETURN_STMT => Stmt::ReturnStmt(ReturnStmt { syntax }),
            SyntaxKind::BREAK_STMT => Stmt::BreakStmt(BreakStmt { syntax }),
            SyntaxKind::BARRIER_STMT => Stmt::BarrierStmt(BarrierStmt { syntax }),
            SyntaxKind::REORDER_STMT => Stmt::ReorderStmt(ReorderStmt { syntax }),
            SyntaxKind::ATOMIC_STMT => Stmt::AtomicStmt(AtomicStmt { syntax }),
            SyntaxKind::ANNOTATED_STMT => Stmt::AnnotatedStmt(AnnotatedStmt { syntax }),
            SyntaxKind::EMPTY_STMT => Stmt::EmptyStmt(EmptyStmt { syntax }),
            _ => return None,
        };
        Some(res)
    }

    fn syntax(&self) -> &SyntaxNode {
        match self {
            Stmt::BlockStmt(it) => it.syntax(),
            Stmt::ExprStmt(it) => it.syntax(),
            Stmt::AssignStmt(it) => it.syntax(),
            Stmt::DeclStmt(it) => it.syntax(),
            Stmt::IfStmt(it) => it.syntax(),
            Stmt::StaticIfStmt(it) => it.syntax(),
            Stmt::ForStmt(it) => it.syntax(),
            Stmt::StaticForStmt(it) => it.syntax(),
            Stmt::WhileStmt(it) => it.syntax(),
            Stmt::DoWhileStmt(it) => it.syntax(),
            Stmt::SwitchStmt(it) => it.syntax(),
            Stmt::ReturnStmt(it) => it.syntax(),
            Stmt::BreakStmt(it) => it.syntax(),
            Stmt::BarrierStmt(it) => it.syntax(),
            Stmt::ReorderStmt(it) => it.syntax(),
            Stmt::AtomicStmt(it) => it.syntax(),
            Stmt::AnnotatedStmt(it) => it.syntax(),
            Stmt::EmptyStmt(it) => it.syntax(),
        }
    }
}

